  static std::vector<SaveMeta> worlds; static bool worldsDirty = true; static double worldsT = 0; static int loadScroll = 0, confirmDel = -1, renameIdx = -1; static std::string renameBuf, statusMsg; static double statusT = 0;
  static void refreshWorlds(Game& g) { worlds = Sv::scan(g.saveDir); worldsDirty = false; worldsT = 0; int maxS = std::max(0, (int)worlds.size() - 1); loadScroll = std::max(0, std::min(loadScroll, maxS)); }
  static void setStatus(const std::string& s) { statusMsg = s; statusT = 6; }
  static int firstPlayable() { for (size_t i = 0; i < worlds.size(); i++) if (worlds[i].ok) return (int)i; return -1; }
  static bool enterWorld(Game& g, const std::string& path) {
    heldId.clear(); heldN = 0; focusField = -1; if (g.loadFile(path)) { g.modal = M_NONE; g.paused = false; POND = Pond(); g.toast("Welcome back to " + g.opts.name + ".", "hint"); Audio::setMood(0); snd("bell", 0.6f); worldsDirty = true; return true; }
    g.modal = M_TITLE; setStatus(g.loadErr.empty() ? "Could not load that world." : g.loadErr); snd("error"); worldsDirty = true; return false; }
  static void startNewGame(Game& g) { GameOpts o; o.name = newName.empty() ? "Hanomi" : newName; bool num = !newSeed.empty() && std::all_of(newSeed.begin(), newSeed.end(), ::isdigit); u32 sd; if (num) sd = (u32)strtoull(newSeed.c_str(), nullptr, 10); else { sd = 2166136261u; for (unsigned char c : newSeed) { sd ^= c; sd *= 16777619u; } } if (newSeed.empty()) sd = (u32)(frand() * 1e9); o.seed = sd; static const char* D[] = {"peaceful", "normal", "hard"}; o.difficulty = D[newDiff]; o.skin = newSkin; o.hair = newHair; o.shirt = newShirt; o.style = newStyle; o.breed = BREEDS[newBreed]; o.dogName = newDog.empty() ? "Kuma" : newDog;
    heldId.clear(); heldN = 0; focusField = -1; g.savePath = Sv::uniquePath(g.saveDir); g.newGame(o); g.modal = M_NONE; g.paused = false; POND = Pond(); g.autosaveT = 0;
    if (!g.saveGame()) g.toast("Warning: this world could not be saved (" + g.loadErr + ")", "bad");
    worldsDirty = true; g.banner("Hanomi", "Welcome home. " + o.dogName + " is happy to see you."); g.toast("WASD to move - Click to use your tool - E to interact", "hint"); g.toast("Tab satchel & crafting - M map - N realm - J journal", "hint"); g.toast("Press E near " + o.dogName + " to give pets.", "hint"); snd("bell"); Audio::setMood(0); }
  static bool xBtn(int x, int y, int w) { int bx = x + w - 38, by = y + 8; ring(bx, by, 30, 30, U, INK); frect(bx, by, 30, 30, over(bx, by, 30, 30) ? SAKURA2 : PAPER2); text("x", bx + 11, by + 3, 18, INK); if (clicked(bx, by, 30, 30)) { snd("close", 0.5f); return true; } return false; }
  static void drawNew(Game& g) { int W = std::min(winW - 40, 900), H = 560, x = (winW - W) / 2, y = std::max(10, (winH - H) / 2); panel(x, y, W, H); panelHeader("A new world", "", x + 22, y + 14, W); int cx = x + 22, ty = y + 60; text("World name", cx, ty, 14, WOOD); textField(cx, ty + 18, 380, newName, 0, 24); text("Seed", cx, ty + 62, 14, WOOD); textField(cx, ty + 80, 290, newSeed, 1, 20); if (button(cx + 298, ty + 80, 82, 34, "Dice", 0, true, 15)) newSeed = std::to_string((u32)(frand() * 1e9));
    text("Difficulty", cx, ty + 126, 14, WOOD); const char* DN[] = {"Peaceful", "Normal", "Hard"}; for (int i = 0; i < 3; i++) { bool hit; seg(cx + i * 128, ty + 146, 120, 32, DN[i], newDiff == i, hit, 16); if (hit) newDiff = i; }
    text("YOU", cx, ty + 196, 14, WOOD); Look L = playerLook(newSkin, newHair, newShirt, newStyle); const CharFrames* F = bakeChar(L); static int fr = 0; fr++; spriteS(F->f[((fr / 24) % 4) == 0 ? 0 : ((fr / 24) % 4) == 1 ? 1 : ((fr / 24) % 4) == 2 ? 0 : 3][1][(fr / 8) % 4], cx, ty + 216, 5);
    int sx = cx + 140; auto sw = [&](int row, const int* cols, int n, int& cur) { for (int i = 0; i < n; i++) { int bx = sx + i * 26, by = ty + 218 + row * 32; ring(bx, by, 22, 22, cur == i ? 3 : 1, cur == i ? SAKURA : INK); frect(bx, by, 22, 22, HEX(cols[i])); if (clicked(bx, by, 22, 22)) { cur = i; snd("click", 0.4f); } } }; sw(0, SKINS, 5, newSkin); sw(1, HAIRS, 9, newHair); sw(2, SHIRTS, 9, newShirt);
    for (int i = 0; i < 5; i++) { bool hit; seg(sx + i * 56, ty + 218 + 96, 52, 26, STYLES[i], newStyle == i, hit, 13); if (hit) newStyle = i; }
    int rx = x + W / 2 + 30; text("YOUR COMPANION", rx, ty, 14, WOOD); const Sprite* dsp = SP(std::string("dog:") + BREEDS[newBreed] + ":sit:" + std::to_string((fr / 20) % 4)); if (dsp) spriteS(dsp->img, rx + 90, ty + 22, 3); text("Name", rx, ty + 150, 14, WOOD); textField(rx, ty + 168, 300, newDog, 2, 14); for (int i = 0; i < 7; i++) { bool hit; seg(rx + (i % 3) * 102, ty + 216 + (i / 3) * 32, 98, 28, BREEDN[i], newBreed == i, hit, 13); if (hit) { newBreed = i; snd("click", 0.4f); } }
    bool begin = button(rx, y + H - 90, 360, 54, "Begin your story", 1, true, 22); if (button(cx, y + H - 90, 120, 54, "Back", 0, true, 20) || xBtn(x, y, W)) { g.modal = M_TITLE; focusField = -1; return; } if (begin) startNewGame(g); }
  static void drawWorldCard(Game& g, int i, int x, int y, int w, bool lock) {
    SaveMeta& m = worlds[i]; int h = 88; bool hv = !lock && over(x, y, w, h); ring(x, y, w, h, 2, INK); frect(x, y, w, h, hv ? 0xFFfffdf4 : 0xFFfff7e2); frect(x, y + h - 4, w, 4, PAPER3);
    frect(x + 8, y + 8, 64, 72, 0xFFd8c8a0); ring(x + 8, y + 8, 64, 72, 1, INK); if (m.ok) { const CharFrames* F = bakeChar(playerLook(m.skin, m.hair, m.shirt, m.style)); spriteS(F->f[0][1][0], x + 8 + 8, y + 8 + 4, 2); }
    std::string nm = m.name; while (nm.size() > 3 && tw(nm, 21) > w - 80 - 230) nm.pop_back(); text(nm, x + 84, y + 8, 21, m.ok ? INK : RED);
    if (m.ok) { std::string d = m.diff; if (!d.empty()) d[0] = (char)toupper(d[0]); text("Day " + std::to_string(m.day) + "  -  " + d + "  -  seed " + std::to_string(m.seed), x + 84, y + 38, 14, 0xFF7a6458); text("Played " + Sv::fmtDur(m.playTime) + "  -  last " + Sv::fmtDate(m.ts) + "  -  with " + m.dog, x + 84, y + 58, 13, 0xFF8a7468); }
    else text("This save file is damaged and can't be opened.", x + 84, y + 40, 14, 0xFF8a7468);
    int bx = x + w - 12; bool en = !lock;
    if (button(bx - 100, y + 10, 100, 34, "Play", 1, en && m.ok, 17)) enterWorld(g, m.path);
    int by = y + 54, bh = 26; bx -= 66; if (button(bx, by, 66, bh, "Delete", 0, en, 13)) { confirmDel = i; snd("click", 0.5f); } bx -= 58; if (button(bx, by, 52, bh, "Copy", 0, en && m.ok, 13)) { std::string np = Sv::uniquePath(g.saveDir); if (Sv::copy(m.path, np)) { SaveMeta nm2; if (Sv::readMeta(np, nm2)) { Sv::renameWorld(np, m.name + " (copy)"); } setStatus("Copied \"" + m.name + "\"."); snd("save"); worldsDirty = true; } else setStatus("Could not copy that world."); } bx -= 76; if (button(bx, by, 70, bh, "Rename", 0, en && m.ok && !m.legacy, 13)) { renameIdx = i; renameBuf = m.name; focusField = 3; snd("click", 0.5f); } }
  static void drawLoad(Game& g) { if (worldsDirty) refreshWorlds(g);
    int W = std::min(winW - 40, 780), H = std::min(winH - 30, 600), x = (winW - W) / 2, y = (winH - H) / 2; panel(x, y, W, H); panelHeader("Your worlds", worlds.empty() ? "" : std::to_string(worlds.size()) + " saved", x + 22, y + 14, W);
    bool lock = confirmDel >= 0 || renameIdx >= 0; int top = y + 62, bottom = y + H - 70, rows = std::max(1, (bottom - top + 8) / 96); int n = (int)worlds.size(); int maxS = std::max(0, n - rows); if (!lock) loadScroll -= IN.wheel; loadScroll = std::max(0, std::min(loadScroll, maxS));
    if (n == 0) { text("No saved worlds yet.", x + 22, y + 90, 19, 0xFF8a7468); text("Start a new one - it is saved automatically as you play.", x + 22, y + 120, 15, 0xFF8a7468); }
    for (int r = 0; r < rows && loadScroll + r < n; r++) drawWorldCard(g, loadScroll + r, x + 22, top + r * 96, W - 44 - (maxS > 0 ? 22 : 0), lock);
    if (maxS > 0) { int sx = x + W - 38, sh = bottom - top; frect(sx, top, 14, sh, PAPER3); int th = std::max(24, sh * rows / n); int ty2 = top + (sh - th) * loadScroll / maxS; frect(sx, ty2, 14, th, WOOD); ring(sx, top, 14, sh, 1, INK); if (!lock && IN.mdown[0] && IN.mouseOn && IN.mx >= sx - 4 && IN.mx < sx + 18 && IN.my >= top && IN.my < bottom) loadScroll = std::max(0, std::min(maxS, (int)((IN.my - top) * (maxS + 1) / sh))); }
    if (button(x + 22, y + H - 58, 140, 42, "Back", 0, !lock, 19) || (!lock && xBtn(x, y, W))) { g.modal = M_TITLE; return; }
    if (!statusMsg.empty() && statusT > 0) text(statusMsg, x + 190, y + H - 48, 15, 0xFF7a6458); else if (n > rows) text("Mouse wheel to scroll", x + 190, y + H - 48, 14, 0xFF8a7468);
    if (confirmDel >= 0 && confirmDel < n) { frect(x, y, W, H, RGB(20, 10, 30, 150)); int w2 = 460, h2 = 190, px = x + (W - w2) / 2, py = y + (H - h2) / 2; panel(px, py, w2, h2); textC("Delete this world?", px + w2 / 2, py + 16, 25, INK, SAKURA2); std::string nm = worlds[confirmDel].name; while (nm.size() > 3 && tw(nm, 18) > w2 - 40) nm.pop_back(); textC("\"" + nm + "\"", px + w2 / 2, py + 62, 18, WOOD); textC("It will be gone forever. This cannot be undone.", px + w2 / 2, py + 90, 14, 0xFF7a6458);
      if (button(px + 24, py + h2 - 64, 190, 42, "Delete forever", 1, true, 17)) { Sv::deleteWorld(worlds[confirmDel].path); setStatus("World deleted."); snd("break"); confirmDel = -1; worldsDirty = true; refreshWorlds(g); } else if (button(px + w2 - 24 - 190, py + h2 - 64, 190, 42, "Keep it", 0, true, 17)) confirmDel = -1; }
    else if (confirmDel >= 0) confirmDel = -1;
    if (renameIdx >= 0 && renameIdx < n) { frect(x, y, W, H, RGB(20, 10, 30, 150)); int w2 = 460, h2 = 190, px = x + (W - w2) / 2, py = y + (H - h2) / 2; panel(px, py, w2, h2); textC("Rename world", px + w2 / 2, py + 16, 25, INK, SAKURA2); textField(px + 24, py + 66, w2 - 48, renameBuf, 3, 24);
      bool ok = !renameBuf.empty() && (button(px + 24, py + h2 - 64, 190, 42, "Save name", 1, true, 17) || IN.p(13)); if (ok) { if (Sv::renameWorld(worlds[renameIdx].path, renameBuf)) setStatus("Renamed."); else setStatus("Could not rename that world."); renameIdx = -1; focusField = -1; worldsDirty = true; refreshWorlds(g); } else if (button(px + w2 - 24 - 190, py + h2 - 64, 190, 42, "Cancel", 0, true, 17)) { renameIdx = -1; focusField = -1; } }
    else if (renameIdx >= 0) renameIdx = -1; }
  static void drawTitle(Game& g, double dt, Img& fb) { titleT += dt; worldsT += dt; statusT -= dt; Modal before = g.modal; if (g.modal == M_TITLE && (worldsDirty || worldsT > 3)) refreshWorlds(g);
    int W = winW, H = winH; T = &fb; frect(0, 0, W, H, HEX(0x1b1420)); int k = std::max(2, (int)std::ceil(std::max(W / 480.0, H / 270.0))); int pw = W / k + 80, ph = H / k + 50; if (TP.w != pw || TP.h != ph) TP.init(pw, ph); TP.step(dt, false); spriteS(TP.img, -40 * k, -25 * k, k);
    for (int y = 0; y < H; y += 4) { double a = 0.35 + 0.35 * std::abs(y - H * 0.5) / (H * 0.5); frect(0, y, W, 4, RGB(20, 10, 30, (int)(a * 170))); }
    if (IN.mhit[0] && g.modal == M_TITLE) { int wx = ((int)IN.mx + 40 * k) / k, wy = ((int)IN.my + 25 * k) / k; if (TP.inWater(wx, wy)) { TP.feed(wx, wy); snd("splash", 0.3f); } }
    int cx = W / 2, ly = H / 2 - 250 > 10 ? H / 2 - 250 : 10; const char* LG = "Hanomi"; int lp = 96, totw = 0; for (int i = 0; i < 6; i++) totw += tw(std::string(1, LG[i]), lp) + 4; int lx = cx - totw / 2; for (int i = 0; i < 6; i++) { int off = (int)std::round(std::sin(titleT * 2 + i * 0.7) * 5); std::string ch(1, LG[i]); text(ch, lx, ly + off, lp, i % 2 ? SAKURA2 : SAKURA, 0xFF2a1020, 5); lx += tw(ch, lp) + 4; } textC("a sakura village survival", cx, ly + 112, 22, 0xFFfff2d0, INK);
    if (g.modal == M_TITLE) { int by = ly + 160, bw = 340; int fp = firstPlayable(); bool cont = fp >= 0;
      if (cont) { std::string lab = "Continue  -  " + worlds[fp].name; while (lab.size() > 6 && tw(lab, 20) > bw - 24) lab.pop_back(); if (button(cx - bw / 2, by, bw, 48, lab, 1, true, 20)) enterWorld(g, worlds[fp].path); by += 58; }
      if (button(cx - bw / 2, by, bw, 48, "New world", cont ? 0 : 1, true, 21)) { g.modal = M_NEW; focusField = -1; } by += 58;
      if (button(cx - bw / 2, by, bw, 48, std::string("Load / manage worlds") + (worlds.empty() ? "" : "  (" + std::to_string(worlds.size()) + ")"), 0, true, 20)) { g.modal = M_LOAD; confirmDel = renameIdx = -1; loadScroll = 0; worldsDirty = true; } by += 58;
      if (button(cx - bw / 2, by, bw, 48, "Settings", 0, true, 21)) { g.modal = M_SETTINGS; fromTitle = true; } by += 58; if (button(cx - bw / 2, by, bw, 48, "How to play", 0, true, 21)) { g.modal = M_HELP; fromTitle = true; } by += 58; if (button(cx - bw / 2, by, bw, 48, "Quit", 0, true, 21)) quitReq = true; }
    const Sprite* ds = SP("dog:bernese:sleep:" + std::to_string(((int)(titleT * 0.8)) % 2)); if (ds) spriteS(ds->img, 40, H - ds->h * 5 - 50, 5); text("Tap the water to feed the koi", W / 2 - tw("Tap the water to feed the koi", 15) / 2, H - 34, 15, 0xFFf6b8ca, INK, 1); text("by Nikit Hamal", W - tw("by Nikit Hamal", 15) - 20, H - 34, 15, 0xFFf6b8ca, INK, 1);
    if (g.modal != before) IN.mhit[0] = false;  // a click that opened a panel must not also press a widget underneath it
    if (g.modal == M_NEW) drawNew(g); else if (g.modal == M_LOAD) drawLoad(g); else if (g.modal == M_SETTINGS && fromTitle) { drawSettings(g); if (g.modal == M_NONE) g.modal = M_TITLE; } else if (g.modal == M_HELP && fromTitle) { drawHelp(g); if (g.modal == M_NONE) g.modal = M_TITLE; }
    if (g.modal == M_TITLE && !statusMsg.empty() && statusT > 0) { int w2 = std::min(W - 40, tw(statusMsg, 17) + 40); int sx = (W - w2) / 2; frect(sx - 2, 18, w2 + 4, 40, INK); frect(sx, 20, w2, 36, 0xFFb84a6a); textC(statusMsg, W / 2, 28, 17, 0xFFffffff, INK, 1); } }
  static void drawModals(Game& g) { T = T; switch (g.modal) { case M_INV: case M_CRAFT: drawInventory(g); break; case M_CHEST: drawChest(g); break; case M_TRADE: drawTrade(g); break; case M_TALK: drawDialog(g, false); break; case M_CHIEF: drawDialog(g, true); break; case M_BANNER: drawBanner(g); break; case M_SOLDIER: drawSoldier(g); break; case M_MAP: drawMap(g); break;
      case M_REALM: drawRealm(g); break; case M_JOURNAL: drawJournal(g); break; case M_PAUSE: drawPause(g); break; case M_SETTINGS: frect(0, 0, winW, winH, RGB(16, 8, 24, 120)); drawSettings(g); break; case M_HELP: frect(0, 0, winW, winH, RGB(16, 8, 24, 120)); drawHelp(g); break; case M_DEAD: drawDead(g); break; default: break; }
    if (!tip.empty()) { int w2 = tw(tip, 15) + 18, x = (int)IN.mx + 16, y = (int)IN.my + 16; if (x + w2 > winW) x = winW - w2 - 4; ring(x, y, w2, 28, U, INK); frect(x, y, w2, 28, 0xFFfffaf0); text(tip, x + 9, y + 4, 15, INK); tip.clear(); } }
